from datetime import datetime, timedelta

# Reuse existing variables if available
print('has coworker_emails', 'coworker_emails' in globals(), 'count', len(coworker_emails) if 'coworker_emails' in globals() else None)
print('has venmo_token', 'venmo_token' in globals(), venmo_token[:10] if 'venmo_token' in globals() else None)
print('has phone_token', 'phone_token' in globals(), phone_token[:10] if 'phone_token' in globals() else None)

today = datetime.now().date()
yesterday = today - timedelta(days=1)
print('today', today, 'yesterday', yesterday)

# Fetch social feed with pagination
page_index = 0
page_limit = 20
all_feed = []
while True:
    resp = apis.venmo.show_social_feed(access_token=venmo_token, page_index=page_index, page_limit=page_limit)
    if isinstance(resp, dict) and 'success' in resp:
        items = resp['success']
    else:
        items = resp
    if not items:
        break
    all_feed.extend(items)
    page_index += 1

print('total_feed_transactions', len(all_feed), 'pages', page_index)

# Filter by created_at date in {yesterday, today}

def parse_date(x):
    # x may be ISO string
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, str):
        # handle 'Z' and timezone
        try:
            return datetime.fromisoformat(x.replace('Z','+00:00')).date()
        except Exception:
            return datetime.strptime(x[:19], '%Y-%m-%dT%H:%M:%S').date()
    return None

selected = []
for t in all_feed:
    cdate = parse_date(t.get('created_at'))
    if cdate == yesterday or cdate == today:
        selected.append(t)

print('selected_yesterday_or_today', len(selected))

# Filter involving coworkers by email in sender or receiver
coworkers = set(e.lower() for e in coworker_emails)
coinvolved = []
for t in selected:
    sender_email = (t.get('sender') or {}).get('email', '')
    receiver_email = (t.get('receiver') or {}).get('email', '')
    if sender_email.lower() in coworkers or receiver_email.lower() in coworkers:
        coinvolved.append(t)

print('coinvolved_count', len(coinvolved))
# show a verification artifact with ids and dates and involved emails
for t in coinvolved[:20]:
    print('tx', t.get('transaction_id'), 'date', parse_date(t.get('created_at')),
          'sender', (t.get('sender') or {}).get('email'),
          'receiver', (t.get('receiver') or {}).get('email'))

print('coinvolved_ids', [t.get('transaction_id') for t in coinvolved])

